slotmap::new_key_type! { pub struct DocumentId; }

pub struct Document {
    pub buffer: TextBuffer,
    pub history: History,
    pub file: Option<FileState>,      // None for an unsaved 'Untitled'
    pub syntax: SyntaxCache,
    pub marks: Vec<Mark>,
    pub name: String,                 // display name; file name or 'Untitled (n)'
    pub config: DocumentConfig,
}

pub struct FileState {
    pub path: std::path::PathBuf,
    pub encoding: kate_fileio::Encoding, pub bom: bool, pub line_ending: kate_fileio::LineEnding,
    pub digest_on_disk: [u8; 32], pub mtime_on_disk: Option<std::time::SystemTime>,
    pub disk_change: Option<DiskChange>,
}
#[derive(Copy, Clone, PartialEq, Eq, Debug)] pub enum DiskChange { Modified, Deleted, Created }

#[derive(Clone, PartialEq, Eq, Debug)] pub struct Mark { pub anchor: Anchor, pub kind: MarkKind }
#[derive(Copy, Clone, PartialEq, Eq, Debug)] pub enum MarkKind { Bookmark, BreakpointActive, BreakpointDisabled, Execution, Warning, Error }

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct DocumentConfig { pub tab_width: u8, pub indent_width: u8, pub indent_with_spaces: bool, pub remove_trailing_spaces: TrailingSpaces, pub ensure_trailing_newline: bool }
#[derive(Copy, Clone, PartialEq, Eq, Debug)] pub enum TrailingSpaces { Never, ModifiedLines, All }

/// Per-line end states, parallel to the buffer's lines. len() == buffer.line_count() after `ensure`.
pub struct SyntaxCache {
    pub definition: Option<DefId>,
    line_end_states: Vec<StateId>,
    dirty_from: Option<u32>,          // first line whose cached state may be wrong
}
impl SyntaxCache {
    pub fn new(definition: Option<DefId>) -> Self;
    /// Called by Workspace after every transaction: splices the vector to the new line count and marks dirty.
    pub fn on_transaction(&mut self, before: &TextBuffer, tx: &Transaction);
    /// Re-highlights from dirty_from until end states converge or `through_line` is reached. Returns the
    /// range of lines whose spans changed so the renderer can invalidate exactly those.
    pub fn ensure(&mut self, buf: &TextBuffer, hl: &mut Highlighter<'_>, through_line: u32) -> std::ops::Range<u32>;
    pub fn start_state(&self, line: u32) -> StateId; // state at the beginning of `line`
}

slotmap::new_key_type! { pub struct ViewId; }

pub struct View {
    pub document: DocumentId,
    pub selections: Selections,
    pub scroll: Scroll,
    pub folds: Vec<CharRange>,        // folded regions, by anchor-resolved ranges in Phase 2; empty until then
    pub dynamic_wrap: bool,
}
#[derive(Copy, Clone, PartialEq, Eq, Debug, Default)]
pub struct Scroll { pub first_line: u32, pub first_col: u32 }

pub struct Workspace {
    pub documents: slotmap::SlotMap<DocumentId, Document>,
    pub views: slotmap::SlotMap<ViewId, View>,
    pub layout: SplitTree,
    pub active_view: Option<ViewId>,
    pub syntax: Repository,
    pub theme: Theme,
    pub config: EditorConfig,
}

pub enum SplitTree {
    Leaf { tabs: Vec<ViewId>, active: usize },
    Split { axis: Axis, ratio: f32, first: Box<SplitTree>, second: Box<SplitTree> },
}
#[derive(Copy, Clone, PartialEq, Eq, Debug)] pub enum Axis { Horizontal, Vertical }

#[derive(Clone, PartialEq, Eq, Debug)]
pub struct EditorConfig { pub default_document: DocumentConfig, pub fallback_encoding: kate_fileio::Encoding }

impl Workspace {
    pub fn new(syntax: Repository, theme: Theme, config: EditorConfig) -> Self;
    pub fn new_document(&mut self) -> DocumentId;
    pub fn open(&mut self, path: &std::path::Path) -> Result<DocumentId, OpenError>; // reuses an open document for the same canonical path
    pub fn new_view(&mut self, doc: DocumentId) -> ViewId; // multiple views per document are normal
    pub fn close_view(&mut self, view: ViewId) -> CloseResult; // last view of a modified document is refused
    pub fn execute(&mut self, view: ViewId, cmd: Command) -> Result<(), CommandError>;
}

#[derive(Debug)] pub enum OpenError { Load(kate_fileio::LoadError), ProbablyBinary(std::path::PathBuf) }
#[derive(Debug, PartialEq, Eq)] pub enum CloseResult { Closed, RefusedModified(DocumentId) }
